from pathlib import Path
import gzip,hashlib,json,time
r=Path('experiments/results/inten_geometric_prior');parent=r/'commands/publication_final_discovery.json';out=r/'publication_final_discovery/worker_receipts';out.mkdir(exist_ok=False)
expected='/tmp/localization-zoo-inten-geometric-prior-20261023/publication_final_discovery'
seen={};end=time.monotonic()+7200
while time.monotonic()<end:
    for folder in Path('/tmp').glob('support_complete_check_*'):
        for p in folder.glob('*_command.json'):
            group=p.name.removesuffix('_command.json')
            if group in seen:continue
            try:row=json.loads(p.read_text())
            except (FileNotFoundError,json.JSONDecodeError):continue
            if row.get('cwd')!=expected or row.get('exit_code') is None:continue
            try:
                artifacts={n:(folder/n).read_bytes() for n in [p.name,group+'.stdout.log',group+'.stderr.log']}
                raw=(folder/(group+'.json')).read_bytes() if row.get('output_sha256') else None
            except FileNotFoundError:continue
            if raw is not None:
                assert hashlib.sha256(raw).hexdigest()==row['output_sha256']
                artifacts[group+'.json.gz']=gzip.compress(raw,mtime=0)
            for n,data in artifacts.items():(out/n).write_bytes(data)
            seen[group]=dict(exit_code=row['exit_code'],output_sha256=row.get('output_sha256'),files_sha256={n:hashlib.sha256(b).hexdigest() for n,b in artifacts.items()})
            print(group,row['exit_code'],flush=True)
    try:done=json.loads(parent.read_text()).get('exit_code') is not None
    except json.JSONDecodeError:done=False
    if done:break
    time.sleep(.1)
else:raise RuntimeError('Discovery receipt did not finish')
(out/'capture.json').write_text(json.dumps(dict(scope='Exact temporary outputs of the fresh discovery, captured after each completed worker receipt.',groups=seen),indent=2)+'\n')
